49	     * segment of the {@code '<REGION>-<HASH8>'} code before the first {@code '-'}, so the locality
50	     * always agrees with the identity's region (which itself prefers the postcode over the city,
51	     * defaulting to {@code 'UNKNOWN'}). Returns {@code 'UNKNOWN'} when no customer code is present.
52	     */
53	    @Named("formatLocality")
54	    default String formatLocality(Owner owner) {
55	        if (owner == null) {
56	            return null;
57	        }
58	        String code = owner.getCustomerCode();
59	        if (code == null || code.isBlank()) {
60	            return "UNKNOWN";
61	        }
62	        int dash = code.indexOf('-');
63	        return dash < 0 ? code : code.substring(0, dash);
64	    }
65	
66	    /**
67	     * Determines an owner's numeric membership level for the read-only {@code membershipLevel}
68	     * field, assigned at creation and ranging from 1 to 3: it starts at 1, gains 1 when an email
69	     * address is present, gains 1 when the owner had no namesakes at creation (namesakeCount is 0),
70	     * and is capped at 3. Level 4 is reserved for tenure.
71	     */
72	    @Named("formatMembershipLevel")
73	    default Integer formatMembershipLevel(Owner owner) {
74	        if (owner == null) {
75	            return null;
76	        }
77	        int level = 1;
78	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
79	        if (hasEmail) {
80	            level++;
81	        }
82	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
83	        if (noNamesakes) {
84	            level++;
85	        }
86	        return Math.min(level, 3);
87	    }
88	
89	    /**
90	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last
91	     * two digits of the registrationDate year (e.g. {@code 'NSW-1A2B3C4D-M26'}), for the read-only
92	     * {@code membershipNumber} field. Null when the customer code or registration date is absent.
93	     */
94	    @Named("formatMembershipNumber")
95	    default String formatMembershipNumber(Owner owner) {
96	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
97	            return null;
98	        }
99	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
100	    }
101	
102	    /**
103	     * Computes the Luhn check digit (0-9) over the digits contained in the owner's
104	     * {@code customerCode} for the read-only {@code checkDigit} field. Null when the
105	     * customer code is absent.
106	     */
107	    @Named("formatCheckDigit")
108	    default Integer formatCheckDigit(Owner owner) {
109	        if (owner == null || owner.getCustomerCode() == null) {
110	            return null;
111	        }
112	        String code = owner.getCustomerCode();
113	        int sum = 0;
114	        boolean dbl = true;
115	        for (int i = code.length() - 1; i >= 0; i--) {
116	            char c = code.charAt(i);
117	            if (c < '0' || c > '9') {
118	                continue;
119	            }
120	            int d = c - '0';
121	            if (dbl) {
122	                d *= 2;
123	                if (d > 9) {
124	                    d -= 9;
125	                }
126	            }
127	            sum += d;
128	            dbl = !dbl;
129	        }
130	        return (10 - (sum % 10)) % 10;
131	    }
132	
133	    /**
134	     * Formats an owner's stored names as {@code 'LastName, FirstName'} for the read-only
135	     * {@code displayName} field.
136	     */
137	    @Named("formatDisplayName")
138	    default String formatDisplayName(Owner owner) {
139	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
140	    }
141	
142	    /**
143	     * Formats an owner's initials as the upper-cased first letters of firstName and
144	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), for the
145	     * read-only {@code initials} field.
146	     */
147	    @Named("formatInitials")
148	    default String formatInitials(Owner owner) {
149	        return owner == null ? null
150	            : Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
151	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
152	    }
153	
154	    Owner toOwner(OwnerDto ownerDto);
155	
156	    @Mapping(target = "id", ignore = true)
157	    @Mapping(target = "pets", ignore = true)
158	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
159	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
160	    Owner toOwner(OwnerFieldsDto ownerDto);
161	
162	    /**
163	     * Normalizes a postal address for persistence: whitespace is trimmed and collapsed, the
164	     * text is upper-cased and common street-type abbreviations are expanded (e.g.
165	     * {@code '  12  main  st '} becomes {@code '12 MAIN STREET'}). The required-field rule is
166	     * enforced separately; an address blank after normalization is rejected.
167	     */
168	    @Named("normalizeAddress")
169	    default String normalizeAddress(String address) {
170	        return AddressNormalizer.normalize(address);
171	    }
172	
173	    /**
174	     * Normalizes a telephone number for persistence into canonical E.164 form (e.g.
175	     * {@code '0412 345 678'} becomes {@code '+61412345678'}). The formability rule is
176	     * enforced separately by {@code TelephoneValidation}.
177	     */
178	    @Named("normalizeTelephone")
179	    default String normalizeTelephone(String telephone) {
180	        return TelephoneNormalizer.toE164(telephone);
181	    }
182	
183	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
184	
185	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
186	
187	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
188	        OwnerPageDto ownerPageDto = new OwnerPageDto();
189	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
190	        ownerPageDto.setPage(ownerPage.getNumber());
191	        ownerPageDto.setSize(ownerPage.getSize());
192	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
193	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
194	        return ownerPageDto;
195	    }
